#include <iostream>
#include <string>

int main() {
    std::string myarray;
    std::cin >> myarray;
    int cnt = 0;
    int len = myarray.length();
    for (int i = 0; i < len; i++) {
        if (myarray[i] == 'Q') {
            for (int j = i + 1; j < len; j++) {
                if (myarray[j] == 'A') {
                    for (int l = j + 1; l < len; l++) {
                        if (myarray[l] == 'Q') {
                            cnt++;
                        }
                    }
                }
            }
        }
    }
    std::cout << cnt;
    return 0;
}

